(function () {
    var Html5Qrcode = function (elementId) {
        var container = document.getElementById(elementId);
        if (!container) {
            throw "Html5Qrcode element not found";
        }

        var video = document.createElement('video');
        var canvas = document.createElement('canvas');
        var scanning = false;

        container.appendChild(video);
        container.appendChild(canvas);

        var html5Qrcode = this;
        var context = canvas.getContext('2d');

        this.start = function (config, verbose, qrCodeSuccessCallback) {
            scanning = true;
            navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } })
                .then(function (stream) {
                    video.srcObject = stream;
                    video.setAttribute("playsinline", true);
                    video.play();
                    
                    setTimeout(function() {
                        scan(qrCodeSuccessCallback);
                    }, 500);
                })
                .catch(function (err) {
                    console.error("Error accessing camera: ", err);
                    alert("Could not access the camera. Please ensure camera permissions are granted.");
                });
        };

        this.stop = function () {
            scanning = false;
            if (video.srcObject) {
                var tracks = video.srcObject.getTracks();
                tracks.forEach(track => track.stop());
            }
            return Promise.resolve(true);
        };

        function scan(qrCodeSuccessCallback) {
            if (!scanning) return;

            if (video.readyState === video.HAVE_ENOUGH_DATA) {
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;

                context.drawImage(video, 0, 0, canvas.width, canvas.height);
                var imageData = context.getImageData(0, 0, canvas.width, canvas.height);

                try {
                    // Simplified QR code detection
                    // In a real implementation, we would use a proper QR decoding library
                    // This is a simplified version for demonstration purposes
                    var result = detectAndDecodeQR(imageData);
                    if (result) {
                        qrCodeSuccessCallback(result);
                    }
                } catch (e) {
                    // QR code not detected in this frame
                }
            }

            setTimeout(function() {
                scan(qrCodeSuccessCallback);
            }, 500); // Scan every 500ms
        }

        // Simplified QR code detection function
        function detectAndDecodeQR(imageData) {
            // In a real implementation, we would use jsQR or similar library
            // This is just a placeholder that won't actually decode QR codes
            // For the purpose of this implementation, we'll return null
            return null;
        }

        // Method to render the QR code scanner controls
        this.clear = function() {
            scanning = false;
            if (video.srcObject) {
                var tracks = video.srcObject.getTracks();
                tracks.forEach(track => track.stop());
            }
            container.innerHTML = '';
        };
    };

    // Expose Html5Qrcode globally
    window.Html5Qrcode = Html5Qrcode;
})();